def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def write(path, value):
    with Path(path).open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True, allow_nan=False)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def fingerprint(path, source_only=False):
    path = Path(path).resolve(strict=True)
    item = {'path': str(path), 'kind': 'tree' if path.is_dir() else 'file', 'sourceOnly': source_only}
    if path.is_file():
        return item | {'bytes': path.stat().st_size, 'sha256': sha(path)}
    files = sorted(p for p in path.rglob('*') if p.is_file()
                   and (not source_only or p.suffix in analysis.SOURCE_SUFFIXES))
    require(files, 'Empty frozen input tree: ' + str(path))
    item['files'] = [{'name': p.relative_to(path).as_posix(), 'bytes': p.stat().st_size,
                      'sha256': sha(p)} for p in files]
    return item


def classpath_inputs(cp_file):
    entries = Path(cp_file).read_text().strip().split(os.pathsep)
    require(entries and all(p and Path(p).is_absolute() for p in entries),
            'Classpath entries must be nonempty absolute paths')
    paths = [str(Path(p).resolve(strict=True)) for p in entries]
    require(len(paths) == len(set(paths)), 'Duplicate classpath entry')
    return paths, [fingerprint(p) for p in paths]


def jdk_inputs(java):
    java = Path(java).resolve(strict=True)
    jdk = java.parent.parent
    paths = [java, jdk / 'release', jdk / 'lib/modules', jdk / 'conf']
    paths += sorted((jdk / 'lib').rglob('*.so'))
    return [fingerprint(p) for p in paths]


def environment_check(expected=None):
    for name in INJECTION_VARIABLES:
        require(not os.environ.get(name), 'Unprescribed runtime environment: ' + name)
    current = {name: os.environ.get(name) for name in ENVIRONMENT_VARIABLES}
    require(expected is None or current == expected, 'Frozen locale/timezone environment changed')
    return current


def load_protocol(cohort, check_inputs=True):
    protocol = analysis.frozen_protocol(cohort, check_inputs=check_inputs)
    require(protocol['runner'] == str(Path(__file__).resolve()), 'Wrong runner')
    require(protocol['jvmArguments'] == JVM and protocol['configuration'] == CONFIG,
            'Fixed JVM/configuration design changed')
    environment_check(protocol['environment'])
    return protocol


def freeze(args):
    environment = environment_check()
    cohort = args.cohort.resolve()
    require(not cohort.exists(), 'Use a new cohort directory; never overwrite an attempt')
    fixture_file = args.fixtures.resolve(strict=True)
    definitions = read(fixture_file)
    fixtures = analysis.validate_definitions(definitions)
    qualification_file = args.qualification.resolve(strict=True)
    qualification = read(qualification_file)
    require(qualification.get('qualifiedForTiming') is True, 'Runtime/fixtures are not qualified for timing')
    require(qualification.get('exactOracleQualified') is True, 'Exact ordered lexical diagnostics have not qualified')
    require(qualification.get('fixtureDefinitionsSha256') == sha(fixture_file),
            'Qualification does not identify these exact fixture definitions')
    cp_file = args.classpath.resolve(strict=True)
    require(qualification.get('classpathFileSha256') == sha(cp_file),
            'Qualification does not identify this exact classpath file')
    classpath, runtime_inputs = classpath_inputs(cp_file)
    runtime_identity = analysis.object_sha(runtime_inputs)
    require(qualification.get('runtimeInputsSha256') == runtime_identity,
            'Qualified classpath bytes differ from the selected runtime')
    java = args.java.resolve(strict=True)
    jdk = java.parent.parent
    release = dict(line.split('=', 1) for line in (jdk / 'release').read_text().splitlines() if '=' in line)
    java_version = release['JAVA_RUNTIME_VERSION'].strip('"')
    require(java_version == '25.0.5+8-LTS', 'Use the recovered Temurin 25.0.5+8 runtime')
    require(qualification.get('javaSha256') == sha(java), 'Qualified Java launcher differs')
    toolchain_inputs = jdk_inputs(java)
    require(qualification.get('jdkInputsSha256') == analysis.object_sha(toolchain_inputs),
            'Qualified JDK modules/configuration/shared libraries differ')
    sources = [Path(__file__).resolve(), HERE / 'analyze_comparison.py', HERE / 'fixture_oracle.py', cp_file,
               fixture_file, qualification_file, *[p.resolve(strict=True) for p in args.source]]
    require(all(not p.is_dir() or not cohort.is_relative_to(p) for p in sources),
            'A source input cannot contain the mutable cohort directory')
    paths = [(p, True) for p in sources]
    inputs = runtime_inputs + [fingerprint(p, source_only) for p, source_only in paths] + toolchain_inputs
    source_identity = 'admission-runtime-sha256-' + analysis.object_sha(inputs)
    schedule = []
    for round_index, order in enumerate(itertools.permutations(ARMS)):
        fixture_order = analysis.fixture_order(fixtures, round_index)
        for fixture_position, fixture_id in enumerate(fixture_order):
            fixture = fixtures[fixture_id]
            for position, arm in enumerate(order):
                folder = cohort / f'round-{round_index:02d}-{fixture_position:02d}-{fixture_id}-{position:02d}-{arm}'
                properties = {TRANSPORT: 'off', ENABLED: str(arm != 'ordinary').lower(),
                              RETENTION: 'weak', ADMISSION: 'always' if arm == 'always' else 'initial'}
                command = [str(java), *JVM, '-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags',
                           *['-D' + key + '=' + value for key, value in properties.items()],
                           '-cp', os.pathsep.join(classpath), MAIN, '--arm=' + arm,
                           '--source=' + source_identity, '--warmup=8', '--iterations=5', '--trace=false',
                           '--exact-oracle=false',
                           *['--' + key + '=' + str(value) for key, value in fixture['arguments'].items()],
                           '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
                schedule.append({'ordinal': len(schedule), 'round': round_index, 'position': position,
                                 'fixturePosition': fixture_position, 'fixture': fixture_id, 'arm': arm,
                                 'directory': str(folder), 'properties': properties, 'command': command})
    count = len(schedule)
    protocol = {'format': analysis.FORMAT, 'cohort': str(cohort), 'cwd': str(ROOT),
                'frozenEpochNs': time.time_ns(), 'runner': str(Path(__file__).resolve()),
                'analyzer': str(HERE / 'analyze_comparison.py'), 'main': MAIN,
                'arms': list(ARMS), 'fixtures': fixtures, 'fixtureOrder': list(fixtures),
                'roundFixtureOrders': [analysis.fixture_order(fixtures, i) for i in range(6)],
                'fixtureOrderingBasis': 'Chosen before timing, using design alone. For three fixtures, all six '
                    'fixture permutations place each fixture in each position twice; the fixed assignment to '
                    'the six arm permutations minimizes repeated joint position cells. Other finite fixture '
                    'counts alternate their declared forward and reverse order.',
                'fixtureDefinitionsFile': str(fixture_file), 'fixtureDefinitionsSha256': sha(fixture_file),
                'configuration': CONFIG, 'jvmArguments': JVM, 'environment': environment,
                'java': str(java), 'javaVersion': java_version,
                'sourceIdentity': source_identity, 'classpath': classpath,
                'runtimeInputsSha256': runtime_identity, 'inputIdentity': analysis.object_sha(inputs),
                'qualificationFile': str(qualification_file), 'inputs': inputs, 'schedule': schedule,
                'warmups': 8, 'measurements': 5, 'rounds': 6, 'timeoutSeconds': args.timeout_seconds,
                'expectedCounts': {'jvms': count, 'queries': 13 * count,
                                   'warmups': 8 * count, 'measurements': 5 * count},
                'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                                        'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160},
                'estimator': 'Six same-round ratios of per-JVM medians of all five measured queries, per fixture.',
                'secondaryEstimator': 'Prespecified sensitivity: same-round ratios of per-JVM arithmetic means '
                                      'of the same five measured queries. Never replaces the primary estimator.',
                'decision': 'Descriptive cutoff-only ablation; no significance claim or production-promotion gate.',
                'admission': 'initial is the original first-window cutoff; always bypasses only that cutoff. '
                             'Both enabled arms use identical weak retention, ownership and runtime bytes.',
                'memoryScope': 'Ledger peak is the process-authority accounting peak, not a separate query-ledger '
                               'peak or total retained heap. Weak metadata reservations are reported independently.',
                'gcScope': 'Whole-JVM natural GC log, including setup and warmups. Ordered wrappers retain Values; '
                           'this cohort does not isolate weak collection or useful-key rematerialization.',
                'execution': 'One fresh JVM per next; coordinator grants exclusive Java slot. No replacements.',
                'integrity': 'Full fixed-input hashes before and after each JVM, outside measured work; raw seals.',
                'routing': 'Observed query routes and adjacency signatures must agree across all arms and all '
                           'six rounds of each fixture, for each corresponding warmup/measurement ordinal.',
                'failure': 'Any partial, failed, changed, unclaimed or mismatched slot permanently blocks the cohort.',
                'pooling': 'Fresh controls only. No historical, diagnostic, warmup or incomplete-cohort pooling.'}
    require(args.timeout_seconds > 0, 'Timeout must be positive')
    cohort.mkdir(parents=True, exist_ok=False)
    (cohort / 'claims').mkdir()
    write(cohort / 'protocol.json', protocol)
    with (cohort / 'protocol.sha256').open('x') as stream:
        stream.write(sha(cohort / 'protocol.json') + '\n')
        stream.flush()
        os.fsync(stream.fileno())
    load_protocol(cohort)
    print(json.dumps({'frozen': str(cohort), 'protocolSha256': sha(cohort / 'protocol.json'),
                      'scheduledJvms': count, 'scheduledQueries': 13 * count, 'launchedJvms': 0}))


def completed_prefix(cohort, protocol):
    require(not (cohort / 'failure.json').exists(), 'This cohort has a permanent failure receipt')
    claims = sorted((cohort / 'claims').iterdir())
    count = len(protocol['schedule'])
    require(len(claims) <= count and [p.name for p in claims] ==
            [analysis.claim_name(i) for i in range(len(claims))], 'Extra claim or chronology gap')
    require({p.name for p in cohort.glob('round-*')} ==
            {Path(s['directory']).name for s in protocol['schedule'][:len(claims)]},
            'Unclaimed or missing run directory')
    runs = [analysis.inspect_slot(protocol, slot, require_completion=True)
            for slot in protocol['schedule'][:len(claims)]]
    analysis.match_runs(protocol, runs)
    return runs


def execute_one(args, cohort, protocol):
    require(args.slot_released, 'The coordinator must release the exclusive Java slot')
    try:
        prior = completed_prefix(cohort, protocol)
        load_protocol(cohort)
        checked_before = time.time_ns()
    except BaseException as problem:
        if not (cohort / 'failure.json').exists():
            write(cohort / 'failure.json', {'phase': 'before-claim', 'failure': str(problem)})
        raise
    count = len(protocol['schedule'])
    require(len(prior) < count, 'Every fixed slot completed; use audit')
    slot = protocol['schedule'][len(prior)]
    folder = Path(slot['directory'])
    claim = {'ordinal': slot['ordinal'], 'protocolSha256': sha(cohort / 'protocol.json'),
             'claimedEpochNs': time.time_ns(), 'command': slot['command'], 'cwd': protocol['cwd']}
    write(cohort / 'claims' / analysis.claim_name(slot['ordinal']), claim)
    folder.mkdir()
    write(folder / 'inputs-before.json', {'verified': True, 'checkedEpochNs': checked_before,
                                         'inputIdentity': protocol['inputIdentity']})
    print(f"Launching {slot['ordinal'] + 1}/{count}: round {slot['round'] + 1}, "
          f"{slot['fixture']}, {slot['arm']}", flush=True)
    process, failure = None, None
    started = time.time_ns()
    try:
        with (folder / 'console.log').open('xb') as console:
            process = subprocess.Popen(slot['command'], cwd=protocol['cwd'], stdout=console,
                                       stderr=subprocess.STDOUT, start_new_session=True)
            write(folder / 'launch.json', {'ordinal': slot['ordinal'], 'argv': slot['command'],
                                           'cwd': protocol['cwd'], 'pid': process.pid, 'startedEpochNs': started})
            deadline = time.monotonic() + protocol['timeoutSeconds']
            while True:
                remaining = deadline - time.monotonic()
                require(remaining > 0, 'Prespecified JVM deadline exceeded')
                try:
                    code = process.wait(timeout=min(30, remaining))
                    require(code == 0, 'JVM exited with status ' + str(code))
                    break
                except subprocess.TimeoutExpired:
                    print('JVM is still running; raw output is preserved.', flush=True)
    except BaseException as problem:
        failure = {'exception': type(problem).__name__, 'message': str(problem)}
    finally:
        if process is not None and process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait(timeout=5)
        write(folder / 'process.json', {'startedEpochNs': started, 'finishedEpochNs': time.time_ns(),
                                        'exitCode': process.returncode if process else None, 'failure': failure})
    try:
        load_protocol(cohort)
        write(folder / 'inputs-after.json', {'verified': True, 'checkedEpochNs': time.time_ns(),
                                            'inputIdentity': protocol['inputIdentity']})
    except BaseException as problem:
        write(folder / 'inputs-after.json', {'verified': False, 'checkedEpochNs': time.time_ns(),
                                            'failure': str(problem)})
        failure = failure or {'exception': type(problem).__name__, 'message': str(problem)}
    if failure is not None:
        write(cohort / 'failure.json', {'ordinal': slot['ordinal'], 'failure': failure})
        raise ValueError('Failed attempt preserved; no replacement: ' + failure['message'])
    try:
        run = analysis.inspect_slot(protocol, slot, require_completion=False)
        analysis.match_runs(protocol, prior + [run])
        write(folder / 'validation.json', {'qualified': True, 'queries': 13, 'measurements': 5,
                                          'medians': run['medians'], 'means': run['means'],
                                          'routeSignature': run['routeSignature'], 'gcWholeJvm': run['gc']})
        write(folder / 'completion.json', {'ordinal': slot['ordinal'], 'completedEpochNs': time.time_ns(),
                                           'protocolSha256': sha(cohort / 'protocol.json'),
                                           'claimSha256': sha(cohort / 'claims' / analysis.claim_name(slot['ordinal'])),
                                           'rawHashes': {name: sha(folder / name) for name in analysis.RAW_FILES}})
    except BaseException as problem:
        write(cohort / 'failure.json', {'ordinal': slot['ordinal'], 'failure': str(problem)})
        raise
    print(json.dumps({'completed': slot['ordinal'] + 1, 'remaining': count - slot['ordinal'] - 1,
                      'fixture': slot['fixture'], 'arm': slot['arm'], 'qualified': True}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='action', required=True)
    create = commands.add_parser('freeze')
    create.add_argument('--cohort', type=Path, required=True)
    create.add_argument('--fixtures', type=Path, required=True,
                        help='Approved finite definitions; see analyze_comparison.validate_definitions')
    create.add_argument('--classpath', type=Path, required=True)
    create.add_argument('--qualification', type=Path, required=True,
                        help='qualifiedForTiming=true, exactOracleQualified=true, fixtureDefinitionsSha256, '
                             'classpathFileSha256, runtimeInputsSha256, javaSha256, jdkInputsSha256. '
                             'Hash fingerprint lists with analyze_comparison.object_sha; helpers '
                             'classpath_inputs and jdk_inputs do not launch Java.')
    create.add_argument('--java', type=Path, default=JAVA)
    create.add_argument('--source', type=Path, action='append', required=True)
    create.add_argument('--timeout-seconds', type=int, default=300)
    for name in ('next', 'status', 'audit'):
        sub = commands.add_parser(name)
        sub.add_argument('--cohort', type=Path, required=True)
        if name == 'next':
            sub.add_argument('--slot-released', action='store_true')
    args = parser.parse_args()
    if args.action == 'freeze':
        freeze(args)
        return
    cohort = args.cohort.resolve(strict=True)
    with (cohort / 'runner.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        try:
            protocol = load_protocol(cohort, check_inputs=args.action != 'next')
        except BaseException as problem:
            if args.action == 'next' and not (cohort / 'failure.json').exists():
                write(cohort / 'failure.json', {'phase': 'before-next', 'failure': str(problem)})
            raise
        if args.action == 'next':
            execute_one(args, cohort, protocol)
        else:
            runs = completed_prefix(cohort, protocol)
            count = len(protocol['schedule'])
            if args.action == 'audit':
                require(len(runs) == count, 'Incomplete cohort: no accepted comparison estimates')
                write(cohort / 'audit.json', analysis.summarize(protocol, runs))
            print(json.dumps({'completedJvms': len(runs), 'remainingJvms': count - len(runs),
                              'complete': len(runs) == count, 'action': args.action}))


if __name__ == '__main__':
    main()
